import { AnimatedIconFrame, type AnimatedIconProps } from "../icon-frame";
import "./star.css";

const starPath =
  "m13.728 3.444l1.76 3.549c.24.494.88.968 1.42 1.058l3.189.535c2.04.343 2.52 1.835 1.05 3.307l-2.48 2.5c-.42.423-.65 1.24-.52 1.825l.71 3.095c.56 2.45-.73 3.397-2.88 2.117l-2.99-1.785c-.54-.322-1.43-.322-1.98 0L8.019 21.43c-2.14 1.28-3.44.322-2.88-2.117l.71-3.095c.13-.585-.1-1.402-.52-1.825l-2.48-2.5C1.39 10.42 1.86 8.929 3.899 8.586l3.19-.535c.53-.09 1.17-.564 1.41-1.058l1.76-3.549c.96-1.925 2.52-1.925 3.47 0";

type Props = AnimatedIconProps & {
  filled?: boolean;
};

export function AnimatedStarIcon({ filled = false, ...props }: Props) {
  return (
    <AnimatedIconFrame name="star" data-filled={filled ? "" : undefined} {...props}>
      <g data-part="star">
        <path data-part="fill" d={starPath} />
        <path d={starPath} />
      </g>
    </AnimatedIconFrame>
  );
}

.animated-icon[data-icon="star"] [data-part="fill"] {
  fill: currentColor;
  stroke: none;
  opacity: 0;
  transform: scale(0);
  transition:
    transform 180ms var(--ease-icon),
    opacity 120ms linear;
}

.animated-icon[data-icon="star"][data-filled] [data-part="fill"] {
  opacity: 1;
  transform: none;
  transition:
    transform 420ms cubic-bezier(0.34, 1.56, 0.64, 1),
    opacity 120ms linear;
}

.animated-icon[data-icon="star"] :is([data-part="star"], [data-part="fill"]) {
  transform-origin: 12px 12.4px;
}

:is([data-icon-hover] .animated-icon, .animated-icon[data-icon-hover], .animated-icon[data-play]) {
  &[data-icon="star"] [data-part="star"] {
    animation-name: icon-star-rock;
    animation-duration: var(--icon-duration-long);
  }
}

@keyframes icon-star-rock {
  18% {
    transform: rotate(-14deg) scale(0.9);
  }
  46% {
    transform: rotate(9deg) scale(1.12);
  }
  72% {
    transform: rotate(-3deg) scale(0.98);
  }
}
